INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q5685145', 'Herrera Period', 'The Herrera Period is a phase in the history of Colombia. It is part of the Andean preceramic and ceramic, time equivalent of the North American pre-Columbian formative and classic stages and age dated by various archaeologists.', -800, NULL, NULL, 800, NULL, NULL, 'year', '800 BCE – 800', 26, 'https://en.wikipedia.org/wiki/Herrera_Period'),
  ('Q21006622', 'Battle of Pasca', 'The Battle of Pasca was fought between the southern Muisca Confederation, led by their zipa (ruler), Saguamanchica, and an alliance between the Panche and the Sutagao, led by the Cacique of Fusagasugá. The battle took place c.', 1470, NULL, NULL, NULL, NULL, NULL, 'year', '1470', 34, 'https://en.wikipedia.org/wiki/Battle_of_Pasca'),
  ('Q5722345', 'Battle of Chocontá', 'The Battle of Chocontá was one of a series of battles in the ongoing conflict between the northern and southern Muisca of pre-Columbian central Colombia. The battle was fought c.', 1490, NULL, NULL, NULL, NULL, NULL, 'year', '1490', 34, 'https://en.wikipedia.org/wiki/Battle_of_Chocont%C3%A1'),
  ('Q2666730', 'Action of August 1702', 'The action of August 1702 was an inconclusive naval battle of the War of the Spanish Succession fought between 19 and 25 August 1702 O.S.. An English squadron under Vice-Admiral of the White John Benbow engaged in a running battle with a smaller French squadron under Admiral Jean-Baptiste du Casse off Santa Marta, Columbia, but insubordination from Benbow''s captains prevented him from inflicting significant damage on du Casse''s squadron, which escaped almost fully intact.', 1702, 9, 4, NULL, NULL, NULL, 'day', '4 September 1702', 43, 'https://en.wikipedia.org/wiki/Action_of_August_1702'),
  ('Q7959512', 'Wager''s Action', 'Wager''s Action was fought on 8 June 1708 between a Royal Navy squadron under Charles Wager and a Franco-Spanish convoy under José de Santillán and Jean-Baptiste du Casse as part of the War of the Spanish Succession. It ended in a British victory, with the Spanish losing two treasure galleons and suffering heavy casualties.', 1708, 6, 8, NULL, NULL, NULL, 'day', '8 June 1708', 43, 'https://en.wikipedia.org/wiki/Wager''s_Action'),
  ('Q2366970', 'Battle of Cartagena de Indias', 'The Battle of Cartagena de Indias (Spanish: Sitio de Cartagena de Indias, lit. ''Siege of Cartagena de Indias'') took place during the 1739 to 1748 War of Jenkins'' Ear between Spain and Great Britain. The result of long-standing commercial tensions, the war was primarily fought in the Caribbean; the British tried to capture key Spanish ports in the region, including Porto Bello and Chagres in Panama, Havana, and Cartagena de Indias in present-day Colombia.', 1741, 3, 13, 1741, 5, 20, 'day', '13 March 1741 – 20 May 1741', 56, 'https://en.wikipedia.org/wiki/Battle_of_Cartagena_de_Indias'),
  ('Q1859495', 'First Republic of New Granada', 'The First Republic of New Granada, known derogatorily as the Foolish Fatherland (Spanish: la Patria Boba), is the period in the history of Colombia immediately following the declaration of independence from Spain in 1810 as the first South American independent nation to break away from Spanish rule until the Spanish reconquest in 1816. The period between 1810 and 1816 in the Viceroyalty of New Granada (which included present-day Colombia) was marked by such intense conflicts over the nature of the new government or governments that it became known as la Patria Boba (the Foolish Fatherland).', 1810, 7, 20, 1816, 10, NULL, 'day', '20 July 1810 – October 1816', 30, 'https://en.wikipedia.org/wiki/First_Republic_of_New_Granada'),
  ('Q3063789', 'Colombian War of Independence', 'The Colombian War of Independence is traditionally held as having begun on July 20, 1810 when a government junta, a political governing board mostly headed by local colonists, was created in Santa Fe de Bogotá, the capital of the Spanish colonial Viceroyalty of New Granada. This junta overthrew the reigning viceroy of New Granada and established an autonomous government that claimed sovereignty over all of the Viceroyalty of New Granada.', 1810, 7, 20, 1825, 4, 2, 'day', '20 July 1810 – 2 April 1825', 56, 'https://en.wikipedia.org/wiki/Colombian_War_of_Independence'),
  ('Q2888371', 'Battle of Cúcuta', 'The Battle of Cúcuta was a military conflict in the Spanish American wars of independence fought on 28 February 1813 between the pro-independence forces led by Simón Bolívar and Spanish royalist troops under General Ramón Correa at the town of Cúcuta, in present-day Colombia, close to the border with Venezuela. Bolivar was victorious.', 1813, 2, 28, NULL, NULL, NULL, 'day', '28 February 1813', 34, 'https://en.wikipedia.org/wiki/Battle_of_C%C3%BAcuta'),
  ('Q1150410', 'Battle of Boyacá', 'The Battle of Boyacá (1819), also known as the Battle of Boyacá Bridge, was a decisive victory by a combined army of Venezuelan and New Granadan troops along with a British Legion led by General Simon Bolivar over the III Division of the Spanish Expeditionary Army of Costa Firme commanded by Spanish Colonel José María Barreiro. This victory ensured the success of Bolívar''s campaign to liberate New Granada.', 1819, 8, 7, NULL, NULL, NULL, 'day', '7 August 1819', 61, 'https://en.wikipedia.org/wiki/Battle_of_Boyac%C3%A1'),
  ('Q2890803', 'Battle of Vargas Swamp', 'The Battle of Vargas Swamp (Spanish: Batalla del Pantano de Vargas) fought on July 25, 1819, was an engagement of Bolívar''s campaign to liberate New Granada. The battle involved a joint Venezuelan and Neogranadine army commanded by General Simón Bolívar against the III Division of the Spanish Royalist Army commanded by Colonel José María Barreiro.', 1819, 7, 25, NULL, NULL, NULL, 'day', '25 July 1819', 37, 'https://en.wikipedia.org/wiki/Battle_of_Vargas_Swamp'),
  ('Q3510584', '1875 Cúcuta earthquake', 'The 1875 Cúcuta earthquake (also known as earthquake of the Andes) occurred on 18 May at 11:15 AM. It completely demolished Cúcuta, Villa del Rosario (Colombia), San Antonio del Tachira and Capacho (Venezuela). The earthquake killed many Venezuelans in San Cristóbal, La Mulata, Rubio, Michelena, La Grita, Colón, amongst others, and was felt in both Bogotá and Caracas.', 1875, 5, 18, NULL, NULL, NULL, 'day', '18 May 1875', 37, 'https://en.wikipedia.org/wiki/1875_C%C3%BAcuta_earthquake'),
  ('Q33930847', 'Putumayo genocide', 'The Putumayo genocide (Spanish: genocidio del Putumayo) refers to the severe exploitation and subsequent ethnocide of the Indigenous population in the Putumayo region. The booms of raw materials incentivized the exploration and occupation of uncolonised land in the Amazon by several South American countries, gradually leading to the subjugation of the local tribes in the pursuit of rubber extraction.', 1879, NULL, NULL, 1912, NULL, NULL, 'year', '1879–1912', 41, 'https://en.wikipedia.org/wiki/Putumayo_genocide'),
  ('Q43378', 'Thousand Days'' War', 'The Thousand Days'' War (Spanish: Guerra de los Mil Días) was a civil war fought in Colombia from 17 October 1899 to 21 November 1902, at first between the Liberal Party and the government led by the National Party, and later – after the Conservative Party had ousted the National Party – between the liberals and the conservative government. Caused by the longstanding ideological tug-of-war of federalism versus centralism between the liberals, conservatives, and nationalists of Colombia following the implementation of the Constitution of 1886 and the political process known as the…', 1899, 10, 17, 1902, 11, 21, 'day', '17 October 1899 – 21 November 1902', 65, 'https://en.wikipedia.org/wiki/Thousand_Days''_War'),
  ('Q106194524', '1900 Colombia coup d''état', 'The 1900 Colombian coup d''état occurred on 31 July of that year, and consisted of the peaceful seizure of power by Vice President José Manuel Marroquín, who, supported by the Conservative Party and the Liberal Party, overthrew Manuel Antonio Sanclemente, member of the National Party. The coup occurred in the context of the Thousand Days'' War, and took advantage of President Sanclemente''s delicate state of health, advanced age, and unpopularity.', 1900, 7, 31, NULL, NULL, NULL, 'day', '31 July 1900', 26, 'https://en.wikipedia.org/wiki/1900_Colombian_coup_d''%C3%A9tat'),
  ('Q2131701', 'Herrán-Hay treaty', 'The Hay–Herrán Treaty was a treaty signed on January 22, 1903, between United States Secretary of State John M. Hay and the diplomat Tomás Herrán of Colombia. Had it been ratified, it would have allowed the United States a renewable lease of 100 years on a six-mile-wide strip across the isthmus of Panama (then part of Colombia) for $10 million and an annual payment of $250,000, both payments being in gold coin.', 1903, 1, 22, NULL, NULL, NULL, 'day', '22 January 1903', 48, 'https://en.wikipedia.org/wiki/Hay%E2%80%93Herr%C3%A1n_Treaty'),
  ('Q3089201', 'separation of Panama from Colombia', 'The secession of Panama from Colombia was formalized on 3 November 1903, with the establishment of the Republic of Panama and the abolition of the Colombia–Costa Rica border. From the independence of Panama from Spain in 1821, Panama had simultaneously joined itself to the confederation of Gran Colombia through the Independence Act of Panama.', 1903, 11, 3, NULL, NULL, NULL, 'day', '3 November 1903', 53, 'https://en.wikipedia.org/wiki/Secession_of_Panama_from_Colombia'),
  ('Q4558519', '1906 Ecuador-Colombia earthquake', 'The 1906 Ecuador–Colombia earthquake occurred at 10:36:10 (UTC+5) on Wednesday, January 31, 1906, off the coast of Ecuador, near Esmeraldas. The earthquake had a moment magnitude of 8.8 and triggered a destructive tsunami that caused at least 500 casualties on the coast of Colombia.', 1906, 1, 31, NULL, NULL, NULL, 'day', '31 January 1906', 47, 'https://en.wikipedia.org/wiki/1906_Ecuador%E2%80%93Colombia_earthquake'),
  ('Q7795915', 'Thomson–Urrutia Treaty', 'The Thomson–Urrutia Treaty was ratified on April 20, 1921, between the United States and Colombia. Based on the terms of the agreement, the U.S. paid Colombia 25 million dollars in return for Colombia''s recognition of Panama''s independence.', 1914, 4, 6, NULL, NULL, NULL, 'day', '6 April 1914', 37, 'https://en.wikipedia.org/wiki/Thomson%E2%80%93Urrutia_Treaty'),
  ('Q1786875', 'Salomón–Lozano Treaty', 'The Salomón–Lozano Treaty was signed in March 1922 by the representatives Fabio Lozano Torrijos of Colombia and Alberto Salomón Osorio of Peru. The fourth in a succession of treaties on the Colombian-Peruvian disputes over land in the Upper Amazon region, it was intended to be a comprehensive settlement of the long border dispute between the two countries.', 1922, 3, 24, NULL, NULL, NULL, 'day', '24 March 1922', 47, 'https://en.wikipedia.org/wiki/Salom%C3%B3n%E2%80%93Lozano_Treaty'),
  ('Q1134821', 'Bananas Massacre in Colombia', 'The Banana Massacre (Spanish: Matanza/Masacre de las bananeras) was a massacre of workers of the United Fruit Company (now Chiquita) that occurred between December 5 and 6, 1928, in the town of Ciénaga near Santa Marta, Colombia. A strike began on November 12, 1928, when the workers ceased to work until the company would reach an agreement with them to grant them dignified working conditions.', 1928, 12, NULL, NULL, NULL, NULL, 'month', 'December 1928', 58, 'https://en.wikipedia.org/wiki/Banana_Massacre'),
  ('Q1536533', 'Colombian-Peruvian War', 'The Colombia–Peru War, also called the Leticia War, was a short-lived armed conflict between Colombia and Peru over territory in the Amazon rainforest that lasted from September 1, 1932, to May 24, 1933. In the end, an agreement was reached to divide the disputed area between both countries.', 1932, 9, 1, 1933, 6, 25, 'day', '1 September 1932 – 25 June 1933', 57, 'https://en.wikipedia.org/wiki/Colombia%E2%80%93Peru_War'),
  ('Q3536710', 'Boundary Treaty of 1941 between Colombia and Venezuela', 'The Colombia–Venezuela Boundary Treaty of 1941, officially the Border Demarcation Agreement and Navigation of the Common Rivers between Colombia and Venezuela, and unofficially the López de Mesa-Gil Borges Treaty, was an agreement signed between the governments of Colombia and Venezuela on the land border limits on April 5, 1941, in Colombian city of Villa del Rosario, Norte de Santander, by the Ministers of Foreign Relations of Venezuela, Esteban Gil Borges, and Colombia, Luis López de Mesa. After almost 60 years of negotiations on the demarcation of the Venezuelan–Colombian border…', 1941, 4, 5, NULL, NULL, NULL, 'day', '5 April 1941', 34, 'https://en.wikipedia.org/wiki/Venezuela%E2%80%93Colombia_Boundary_Treaty_of_1941'),
  ('Q2327438', 'Bogotazo', 'El Bogotazo (from "Bogotá" and the -azo suffix of violent augmentation) was a massive outbreak of rioting after the assassination in Bogotá, Colombia of Liberal leader and presidential candidate Jorge Eliécer Gaitán on 9 April 1948 during the government of President Mariano Ospina Pérez. The 10-hour riot left much of downtown Bogotá destroyed.', 1948, 4, 9, NULL, NULL, NULL, 'day', '9 April 1948', 52, 'https://en.wikipedia.org/wiki/Bogotazo'),
  ('Q185407', 'La Violencia', 'La Violencia (Spanish pronunciation: [la βjoˈlensja], The Violence) was a ten-year wave of civil conflict and unrest in Colombia from 1948 to 1958, between the Colombian Conservative Party and the Colombian Liberal Party, mainly fought in the countryside. La Violencia is considered to have begun with the assassination on 9 April 1948 of Jorge Eliécer Gaitán, a Liberal Party presidential candidate and frontrunner for the 1949 November election.', 1949, 12, 6, 1958, NULL, NULL, 'day', '6 December 1949 – 1958', 60, 'https://en.wikipedia.org/wiki/La_Violencia'),
  ('Q8663', 'Korean War', 'The Korean War (25 June 1950 – 27 July 1953) was an armed conflict fought on the Korean Peninsula between North Korea (Democratic People''s Republic of Korea; DPRK) and South Korea (Republic of Korea; ROK) and their allies. North Korea was supported by China and the Soviet Union, while South Korea was supported by the United Nations led by the United States under the auspices of the United Nations Command (UNC).', 1950, 6, 25, 1953, 7, 27, 'day', '25 June 1950 – 27 July 1953', 94, 'https://en.wikipedia.org/wiki/Korean_War'),
  ('Q492671', 'Battle of Triangle Hill', 'The Battle of Triangle Hill, also known as Operation Showdown or the Shangganling Campaign (Chinese: 上甘岭战役; pinyin: Shànggānlǐng Zhànyì), was a protracted military engagement during the Korean War. The main combatants were two United Nations (UN) infantry divisions, with additional support from the United States Air Force, against elements of the Chinese People''s Volunteer Army (PVA) 15th and 12th Corps.', 1952, 10, 14, 1952, 11, 25, 'day', '14 October 1952 – 25 November 1952', 41, 'https://en.wikipedia.org/wiki/Battle_of_Triangle_Hill'),
  ('Q5147882', '1953 Colombian coup d''état', 'The 1953 Colombian coup d''état was the bloodless coup followed by seizing of power from Conservative President Laureano Gómez, by Colombia''s commander in chief Gustavo Rojas Pinilla on June 13, 1953. Colombia was ruled by Rojas Pinilla''s military dictatorship until the Colombian coup of May 10, 1957, when he was forced to step down and hand over power to a military junta.', 1953, 6, 13, NULL, NULL, NULL, 'day', '13 June 1953', 26, 'https://en.wikipedia.org/wiki/1953_Colombian_coup_d''%C3%A9tat'),
  ('Q169072', 'Colombian conflict', 'The Colombian conflict (Spanish: Conflicto armado interno de Colombia, lit. ''Colombian internal armed conflict'') began on May 27, 1964, and is a low-intensity asymmetric war between the government of Colombia, paramilitary groups, crime syndicates, and far-left guerrilla groups engaged in armed factional hostilities to increase their influence in Colombian territory. Some of the most important international contributors to the Colombian conflict include multinational corporations, the United States, Cuba, and the drug trafficking industry.', 1964, 5, 27, NULL, NULL, NULL, 'day', '27 May 1964', 71, 'https://en.wikipedia.org/wiki/Colombian_conflict'),
  ('Q4828576', 'Avianca Flight 4', 'Avianca Flight 03 was a passenger flight from Cartagena, Colombia, to Bogotá, Colombia, that crashed on January 14, 1966. After takeoff, as the aircraft reached 100 ft (30 m), it stalled and crashed into shallow water.', 1966, 1, 15, NULL, NULL, NULL, 'day', '15 January 1966', 45, 'https://en.wikipedia.org/wiki/Avianca_Flight_03'),
  ('Q4355011', '1980 Dominican Embassy Siege in Bogotá', 'The Dominican Republic Embassy siege was the 1980 siege of the embassy of the Dominican Republic by M-19 guerrillas in Bogotá, Colombia. The guerrillas held nearly 60 people, including 15 ambassadors, hostage.', 1980, 2, 27, 1980, 4, 27, 'day', '27 February 1980 – 27 April 1980', 41, 'https://en.wikipedia.org/wiki/1980_Dominican_Republic_Embassy_siege_in_Bogot%C3%A1'),
  ('Q829836', 'Palace of Justice Siege', 'The Palace of Justice siege was an attack carried out in Bogotá, Colombia, on November 6–7, 1985, in which a guerrilla commando of the 19th of April Movement (M-19) took over the Palace of Justice, housing the Supreme Court and the Council of State. The guerrillas held roughly 350 people hostage, among them Supreme Court justices, councilors of state, judicial staff, employees, and visitors.', 1985, 11, 6, NULL, NULL, NULL, 'day', '6 November 1985', 50, 'https://en.wikipedia.org/wiki/Palace_of_Justice_siege'),
  ('Q2532815', 'Armero tragedy', 'The Armero tragedy (Spanish: Tragedia de Armero [tɾaˈxeðja ðe aɾˈmeɾo]) occurred following the eruption of the Nevado del Ruiz stratovolcano in Tolima, Colombia, on November 13, 1985. The volcano''s eruption after 69 years of dormancy caught nearby towns unprepared, even though volcanological organizations had warned the government to evacuate the area after they had detected volcanic activity two months earlier.', 1985, 11, 13, NULL, NULL, NULL, 'day', '13 November 1985', 57, 'https://en.wikipedia.org/wiki/Armero_tragedy'),
  ('Q3087069', 'Avianca Flight 410', 'Avianca Flight 410 was a Boeing 727-21 that crashed at 13:17 on 17 March 1988, near Cúcuta, Colombia, which occurred shortly after takeoff during a scheduled flight when it flew into a mountain. All 143 people on board were killed.', 1988, 3, 17, NULL, NULL, NULL, 'day', '17 March 1988', 51, 'https://en.wikipedia.org/wiki/Avianca_Flight_410'),
  ('Q7388641', 'SAM Colombia Flight 501', 'SAM Colombia Flight 501 was a Boeing 727-46 that crashed on 19 May 1993, killing all 132 on board. The aircraft collided with a mountain while on approach to Medellín, Colombia.', 1993, 5, 19, NULL, NULL, NULL, 'day', '19 May 1993', 48, 'https://en.wikipedia.org/wiki/SAM_Colombia_Flight_501'),
  ('Q3510586', '1994 Paez river earthquake', 'The 1994 Páez River earthquake occurred on June 6 with a moment magnitude of 6.8 at a depth of 12 km (7.5 mi). The event, which is also known as the Páez River disaster, included subsequent landslides and mudslides that destroyed much of the Páez municipality, located on the foothills of the Central Ranges of the Andes in Cauca in south-western Colombia.[1] It was estimated that 1,100 people, mostly from the Páez, were killed in some 15 settlements on the Páez River basin, Cauca and Huila departments of which the eponymous municipality of Páez suffered 50% of the death toll.[2][3] In…', 1994, 6, 6, NULL, NULL, NULL, 'day', '6 June 1994', 34, 'https://en.wikipedia.org/wiki/1994_P%C3%A1ez_River_earthquake'),
  ('Q941612', 'American Airlines Flight 965', 'American Airlines Flight 965 was a regularly scheduled flight from Miami International Airport in Miami, Florida, to Alfonso Bonilla Aragón International Airport in Cali, Colombia. On December 20, 1995, the Boeing 757 flying this route crashed into a mountain in Buga, Colombia, around 9:40 pm local time killing 151 of the 155 passengers and all 8 crew members.', 1995, 12, 20, NULL, NULL, NULL, 'day', '20 December 1995', 60, 'https://en.wikipedia.org/wiki/American_Airlines_Flight_965'),
  ('Q13441139', 'Intercontinental de Aviación Flight 256', 'Intercontinental de Aviación Flight 256 was a scheduled flight from El Dorado International Airport, Bogotá, on a service to Rafael Núñez International Airport, Cartagena, and San Andrés. On 11 January 1995, the McDonnell Douglas DC-9-14 operating the flight flew into the ground during its approach to Cartagena Airport, killing all but one of the 52 people on board.', 1995, 1, 11, NULL, NULL, NULL, 'day', '11 January 1995', 48, 'https://en.wikipedia.org/wiki/Intercontinental_de_Aviaci%C3%B3n_Flight_256'),
  ('Q1626132', 'Mapiripán Massacre', 'The Mapiripán massacre was a massacre of civilians that took place in Mapiripán, Meta Department, Colombia. The massacre was carried out from July 15–20, 1997, by the United Self-Defence Forces of Colombia (AUC), an outlawed right-wing paramilitary group.', 1997, 7, 20, NULL, NULL, NULL, 'day', '20 July 1997', 34, 'https://en.wikipedia.org/wiki/Mapirip%C3%A1n_massacre'),
  ('Q3083143', 'Air France Flight 422', 'Air France Flight 422 was a scheduled flight on 20 April 1998 by Air France from Bogotá, Colombia, to Quito, Ecuador, covering the final leg of a flight from Paris to Quito. The Boeing 727 was destroyed, killing all 53 people on board, when it crashed into the Eastern Hills of Bogotá because of foggy weather and low visibility after taking off from Bogotá''s El Dorado International Airport.', 1998, 4, 20, NULL, NULL, NULL, 'day', '20 April 1998', 48, 'https://en.wikipedia.org/wiki/Air_France_Flight_422'),
  ('Q497145', '1999 Armenia, Colombia earthquake', 'The 1999 Colombia earthquake occurred on 25 January 1999 at 13:19 with an epicenter 40 kilometers (25 mi) west southwest of Ibagué, Colombia. The shock heavily affected the city of Armenia in the Quindío department, and about 18 other towns and 28 additional villages in the Colombian Coffee-Growers Axis region departments, and to a lesser degree, the cities of Pereira and Manizales.', 1999, 1, 25, NULL, NULL, NULL, 'day', '25 January 1999', 48, 'https://en.wikipedia.org/wiki/1999_Colombia_earthquake'),
  ('Q779179', 'false positives in Colombia', 'The "false positives" scandal (Spanish: Escándalo de los falsos positivos) was a series of murders in Colombia, part of the armed conflict in that country between the government and guerrilla forces of the FARC and the ELN. Members of the military and their civilian collaborators lured poor or mentally impaired civilians to remote parts of the country with offers of work, killed them, and presented them to authorities as guerrilleros killed in battle, in an effort to inflate body counts and receive promotions or other benefits. While Colombian investigative agencies have found cases as…', 2002, NULL, NULL, NULL, NULL, NULL, 'year', '2002', 47, 'https://en.wikipedia.org/wiki/%22False_positives%22_scandal'),
  ('Q9094823', 'TAME Flight 120', 'TAME Flight 120 was a Boeing 727-134 airliner, registration HC-BLF, named El Oro, operating as a scheduled international passenger flight between Quito, Ecuador and Cali, Colombia, with a scheduled stopover at the Ecuadorian border town of Tulcán. The aircraft crashed while on approach to Tulcán''s Teniente Coronel Luis A. Mantilla International Airport on January 28, 2002.', 2002, 1, 28, NULL, NULL, NULL, 'day', '28 January 2002', 47, 'https://en.wikipedia.org/wiki/TAME_Flight_120'),
  ('Q4610947', '2008 El Calvario earthquake', 'The 2008 El Calvario earthquake occurred in central Colombia on 24 May and measured 5.9 on the moment magnitude scale. The earthquake occurred at 2:20:43 p.m.', 2008, 5, 24, NULL, NULL, NULL, 'day', '24 May 2008', 37, 'https://en.wikipedia.org/wiki/2008_El_Calvario_earthquake'),
  ('Q4651994', 'AIRES Flight 8250', 'AIRES Flight 8250 was a domestic scheduled passenger flight that on 16 August 2010 crashed on landing at night in poor weather on the Colombian island of San Andrés, killing two of the 131 people on board. The aircraft, an AIRES-operated Boeing 737-700, was arriving from the Colombian capital Bogotá when it heavily touched down short of the runway, breaking up in three sections.', 2010, 8, 16, NULL, NULL, NULL, 'day', '16 August 2010', 48, 'https://en.wikipedia.org/wiki/AIRES_Flight_8250'),
  ('Q5858325', 'Colombian peace process', 'The Colombian peace process is the negotiations between the Government of Colombia under President Juan Manuel Santos and the Revolutionary Armed Forces of Colombia (FARC–EP) aimed at ending the decades-long Colombian conflict. Formal negotiations began in September 2012 and were primarily held in Havana, Cuba.', 2016, 9, 26, NULL, NULL, NULL, 'day', '26 September 2016', 37, 'https://en.wikipedia.org/wiki/Colombian_peace_process'),
  ('Q26840027', 'Colombian peace agreement referendum, 2016', 'The Colombian peace agreement referendum was held on 2 October 2016, aiming to ratify the final agreement on the termination of the Colombian conflict between the Colombian government and the FARC guerillas. It failed, with 50.2% voting against it and 49.8% voting in favor.', 2016, 10, 2, NULL, NULL, NULL, 'day', '2 October 2016', 52, 'https://en.wikipedia.org/wiki/2016_Colombian_peace_agreement_referendum'),
  ('Q27925924', 'LaMia Flight 2933', 'LaMia Flight 2933 was a regularly scheduled charter flight from Santa Cruz de la Sierra, Bolivia, to Medellín, Colombia. On 28 November 2016, the aircraft operating the flight crashed into Mt.', 2016, 11, 28, NULL, NULL, NULL, 'day', '28 November 2016', 71, 'https://en.wikipedia.org/wiki/LaMia_Flight_2933'),
  ('Q28043715', 'Aerosucr Fliht666', 'Aerosucre Flight 157 was a domestic cargo flight from Germán Olano Airport in Puerto Carreño, Colombia, to El Dorado International Airport, Bogotá. On 20 December 2016, the Boeing 727-2J0F operating the route overran the runway during takeoff, striking the perimeter fence and other obstacles before becoming airborne, ultimately losing control and crashing 4 nmi (4.6 mi; 7.4 km) from the airport.', 2016, 12, 20, NULL, NULL, NULL, 'day', '20 December 2016', 50, 'https://en.wikipedia.org/wiki/Aerosucre_Flight_157'),
  ('Q66474138', 'Catatumbo campaign', 'The Catatumbo campaign has been an ongoing period of strategic violence between militia faction groups in the Catatumbo region of Colombia and Venezuela since January 2018. It is an extension of the war on drugs and developed after the Colombian peace process of 2016.', 2018, 1, NULL, NULL, NULL, NULL, 'month', 'January 2018', 30, 'https://en.wikipedia.org/wiki/Catatumbo_campaign'),
  ('Q75230417', '2018–20 Colombian protests', 'The 2019–2020 Colombian protests were a collection of protests that began on 21 November 2019. Hundreds of thousands of Colombians demonstrated for various reasons.', 2019, 11, 21, NULL, NULL, NULL, 'day', '21 November 2019', 45, 'https://en.wikipedia.org/wiki/2019%E2%80%932020_Colombian_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q106668058', '2021 Colombian protests', 'A series of protests began in Colombia on 28 April 2021 against increased taxes, corruption, and health care reform proposed by the government of President Iván Duque. The tax initiative was introduced to expand funding to Ingreso Solidario, a universal basic income social program established in April 2020 to provide relief during the COVID-19 pandemic in Colombia, while the legislative Bill 010 proposed several changes in the health care system in Colombia.', 2021, 4, 28, 2022, NULL, NULL, 'day', '28 April 2021 – 2022', 56, 'https://en.wikipedia.org/wiki/2021_Colombian_protests'),
  ('Q109783491', '2021 Amazonas earthquake', 'A major earthquake struck northern Peru on November 28, 2021, 5:52 a.m. local time with a magnitude of 7.5 on the moment magnitude scale between the Amazonas and Loreto departments of Peru.', 2021, 11, 28, NULL, NULL, NULL, 'day', '28 November 2021', 43, 'https://en.wikipedia.org/wiki/2021_Northern_Peru_earthquake'),
  ('Q119293280', '2023 Colombia Cessna 206 crash and rescue operation in the Amazon Rainforest', 'On 1 May 2023, a Cessna 206 light aircraft with seven people on board crashed in the jungle in the Caquetá Department of Colombia. Two of the occupants – the pilot and co-pilot were killed on impact, while four passengers survived the crash.', 2023, 5, 1, NULL, NULL, NULL, 'day', '1 May 2023', 52, 'https://en.wikipedia.org/wiki/2023_Caquet%C3%A1_Cessna_Stationair_crash'),
  ('Q131838925', '2025 Catatumbo attacks', 'On 16 January 2025, National Liberation Army (ELN) militants launched several attacks against FARC dissidents in the Catatumbo region of Colombia, as part of the Catatumbo campaign. At least 103 people have been killed in the attacks, with others injured, kidnapped, and displaced.', 2025, 1, 16, NULL, NULL, NULL, 'day', '16 January 2025', 41, 'https://en.wikipedia.org/wiki/2025_Catatumbo_clashes'),
  ('Q134734156', 'assassination of Miguel Uribe Turbay', 'On 7 June 2025, Miguel Uribe Turbay, a senator and pre-candidate in the 2026 Colombian presidential election, was shot during a rally at El Golfito Park in the neighbourhood of Modelia, part of the locality of Fontibón, in Bogotá, Colombia. He was hospitalised in critical condition and died two months later from his injuries.', 2025, 6, 7, NULL, NULL, NULL, 'day', '7 June 2025', 45, 'https://en.wikipedia.org/wiki/Assassination_of_Miguel_Uribe_Turbay'),
  ('Q137921022', '8849 SATENA flight', 'On 28 January 2026, SATENA Flight 8849, a scheduled domestic flight in Colombia from Camilo Daza International Airport in Cúcuta to Aguas Claras Airport in Ocaña, crashed in Curasica, Playa de Belén, Norte de Santander. The Beechcraft 1900 operating the flight was carrying 13 passengers and two crew members.', 2026, 1, 28, NULL, NULL, NULL, 'day', '28 January 2026', 47, 'https://en.wikipedia.org/wiki/SATENA_Flight_8849'),
  ('Q138773815', '2026 Colombian Air Force Lockheed C-130 crash', 'On 23 March 2026, a Colombian Aerospace Force Lockheed C-130 Hercules crashed into dense jungle while taking off from Caucayá Airport in Puerto Leguízamo en route to Tres de Mayo Airport in Puerto Asís, both located in Colombia''s Putumayo department near the border with Peru and Ecuador. There were 126 people on board, of whom 69 were killed, and 57 survived with injuries.', 2026, 3, 23, NULL, NULL, NULL, 'day', '23 March 2026', 57, 'https://en.wikipedia.org/wiki/2026_Colombian_Air_Force_Lockheed_C-130_crash'),
  ('Q140984463', '2026 Colombia earthquake', 'On 10 August 2026, a Mw 7.4–7.5 earthquake struck the department of Chocó in Colombia, killing at least 335 people, injuring more than 4,600 others, leaving 111 confirmed missing and causing extensive damage across the country. The earthquake was felt across much of western and central Colombia and in parts of neighbouring Ecuador and Panama, and caused extensive damage in Cali, Pereira, Quibdó, Manizales, Armenia, Buenaventura, and other areas.', 2026, 8, 10, NULL, NULL, NULL, 'day', '10 August 2026', 67, 'https://en.wikipedia.org/wiki/2026_Colombia_earthquake');
